import { IconButton } from "../buttons/icon-button";
import { cx } from "../../utils/cx";

type RootRenderProps = ComponentProps<CollectionRenderer["CollectionRoot"]>;
const easing = [.22,1,.36,1] as const;
function AnimatedRow({id,children}:{id:Key;children:ReactNode}){
 const present=useIsPresent(),reduced=useReducedMotion(),state=useContext(TreeStateContext),snapshot=useRef(state),root=useRef<HTMLDivElement>(null);
 if(present&&state?.collection.getItem(id))snapshot.current=state;
