 return <motion.div ref={root} role="presentation" aria-hidden={!present||undefined} data-tree-view-exiting={!present||undefined} className="relative min-w-0 shrink-0 overflow-hidden"
   initial={reduced?false:{height:0,paddingTop:0,paddingBottom:0,opacity:0,filter:"blur(4px)",y:-4}}
   animate={{height:"auto",paddingTop:1,paddingBottom:1,opacity:1,filter:"blur(0px)",y:0}}
   exit={{height:0,paddingTop:0,paddingBottom:0,opacity:0,filter:"blur(4px)",y:-4}} transition={{duration:reduced?0:.28,ease:easing}}>
   <TreeStateContext.Provider value={present?state:snapshot.current}>{children}</TreeStateContext.Provider>
 </motion.div>
}
function AnimatedCollection({collection}:RootRenderProps){
 return <AnimatePresence initial={false}>{Array.from(collection,node=>{
  if(node.type==="content")return null;
  // Collection renderers receive renderable nodes from the collection builder.
  if(!("render"in node)||typeof node.render!=="function")return null;
  const render=node.render as (item:typeof node)=>ReactNode;
  return <AnimatedRow key={node.key} id={node.key}>{render(node)}</AnimatedRow>;
 })}</AnimatePresence>
}
const renderer:CollectionRenderer={...DefaultCollectionRenderer,CollectionRoot:AnimatedCollection};
export interface TreeViewProps<T> extends Omit<TreeProps<T>,"dragAndDropHooks"> { size?:"md"|"sm";showGuides?:boolean }
function TreeViewInner<T>({size="md",showGuides=true,selectionMode="single",selectionBehavior=selectionMode==="multiple"?"toggle":"replace",className,...props}:TreeViewProps<T>,ref:React.ForwardedRef<HTMLDivElement>){
 return <CollectionRendererContext.Provider value={renderer}><AriaTree {...props} ref={ref} selectionMode={selectionMode} selectionBehavior={selectionBehavior} data-size={size} data-show-guides={showGuides}
 className={state=>cx("group/tree-view flex w-full min-w-0 flex-col gap-0 rounded-3xl border border-border-button-default bg-background-primary-default p-2 outline-none data-[empty]:px-4 data-[empty]:py-8 data-[empty]:text-center data-[empty]:text-body-regular data-[empty]:text-text-tertiary data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring",typeof className==="function"?className(state):className)}/></CollectionRendererContext.Provider>
}
export const TreeView=forwardRef(TreeViewInner) as <T>(props:TreeViewProps<T>&RefAttributes<HTMLDivElement>)=>ReactElement;
export const TreeViewCollection=Collection;
type Icon = ComponentType<{className?:string;"aria-hidden"?:boolean|"true"|"false"}>;
export interface TreeViewItemProps<T=object> extends Omit<TreeItemProps<T>,"children"|"textValue">{
 label:ReactNode;
 textValue?:string;
 children?:ReactNode;
 icon?:Icon;
 expandedIcon?:Icon;
 iconClassName?:string;
