 onKeyDownCapture?:(event:KeyboardEvent<HTMLDivElement>)=>void;
}

function Guides({row}:{row:TreeItemContentRenderProps}){
 const state=useContext(TreeStateContext);if(!state)return null;
 const node=state.collection.getItem(row.id);if(!node)return null;
 const hasNext=(item:typeof node)=>{let key=item.nextKey;while(key!=null){const next=state.collection.getItem(key);if(!next)return false;if(next.type==="item")return true;key=next.nextKey}return false};
 const ancestors:typeof node[]=[];let key=node.parentKey;while(key!=null){const parent=state.collection.getItem(key);if(!parent)break;ancestors.unshift(parent);key=parent.parentKey}
 const position=(depth:number)=>`calc(1.125rem + ${depth} * 1.25rem)`,width=row.hasChildItems?12:16;
 return <span aria-hidden data-tree-view-guides className="pointer-events-none absolute inset-0 text-foreground-icon-quaternary group-data-[show-guides=false]/tree-view:hidden">
  {ancestors.slice(1).map((ancestor,index)=>hasNext(ancestor)&&<span key={ancestor.key} data-tree-view-trunk className="absolute -inset-y-px w-px bg-current" style={{insetInlineStart:position(index)}}/>)}
  {row.level>1&&<span data-tree-view-branch className="absolute -inset-y-px" style={{insetInlineStart:position(row.level-2),width}}>
   <span className="absolute start-0 top-0 w-px bg-current" style={{bottom:"calc(50% + 6px)"}}/>
   <svg width={width} height="7" viewBox={`0 0 ${width} 7`} fill="none" className="absolute start-0 rtl:-scale-x-100" style={{top:"calc(50% - 6px)"}}><path d={`M0.5 0 Q0.5 6 6.5 6 H${width-.5}`} stroke="currentColor" strokeWidth="1"/></svg>
   {hasNext(node)&&<span data-tree-view-tail className="absolute start-0 bottom-0 w-px bg-current" style={{top:"calc(50% - 6px)"}}/>}
  </span>}
  {row.hasChildItems&&row.isExpanded&&<span data-tree-view-bridge className="absolute -bottom-px w-px bg-current" style={{insetInlineStart:position(row.level-1),top:"calc(50% + 8px)"}}/>}
 </span>
}
function fileTone(label:string){if(/\.[jt]sx?$/i.test(label))return"text-accent-700";if(/\.css$/i.test(label))return"text-chart-5-active";if(/\.md$/i.test(label))return"text-chart-1-active";if(/\.json$/i.test(label))return"text-foreground-icon-secondary";return"text-foreground-icon-primary"}
function TreeRow({domProps,customRender,renderProps,id,onKeyDownCapture}:{domProps:React.HTMLAttributes<HTMLDivElement>;customRender?:TreeViewItemProps["render"];renderProps:Parameters<NonNullable<TreeViewItemProps["render"]>>[1];id:Key;onKeyDownCapture?:TreeViewItemProps["onKeyDownCapture"]}){
 const state=useContext(TreeStateContext),{direction}=useLocale();
 const navigate=(event:KeyboardEvent<HTMLDivElement>)=>{
  onKeyDownCapture?.(event);if(event.defaultPrevented||event.target!==event.currentTarget||!state)return;
  const node=state.collection.getItem(id);if(!node)return;
  const forward=direction==="rtl"?"ArrowLeft":"ArrowRight",back=direction==="rtl"?"ArrowRight":"ArrowLeft";let target:Key|null=null,handled=false;
  if(event.key===forward&&node.hasChildNodes){handled=true;if(!state.expandedKeys.has(node.key))state.toggleKey(node.key);else target=Array.from(state.collection.getChildren?.(node.key)??[]).find(n=>n.type==="item")?.key??null}
  else if(event.key===back){handled=true;if(state.expandedKeys.has(node.key))state.toggleKey(node.key);else target=node.parentKey??null}
  if(!handled)return;event.preventDefault();event.stopPropagation();if(target!=null){state.selectionManager.setFocusedKey(target);const rows=event.currentTarget.closest('[role="treegrid"]')?.querySelectorAll<HTMLElement>('[role="row"]');Array.from(rows??[]).find(row=>row.dataset.key===String(target))?.focus()}
 };
 return customRender?customRender({...domProps,onKeyDownCapture:navigate},renderProps):<div {...domProps} onKeyDownCapture={navigate}/>;
}
function TreeViewItemInner<T>({label,textValue,children,icon,expandedIcon,iconClassName,trailingContent,className,style,onKeyDownCapture,render:renderRow,...props}:TreeViewItemProps<T>,ref:React.ForwardedRef<HTMLDivElement>){
 const {direction}=useLocale();
 const text=textValue??(typeof label==="string"||typeof label==="number"?String(label):props["aria-label"]??"");
 return <AriaTreeItem {...props} render={(domProps,renderProps)=><TreeRow domProps={domProps} customRender={renderRow} renderProps={renderProps} id={props.id!} onKeyDownCapture={onKeyDownCapture}/>} ref={ref} textValue={text} aria-label={props["aria-label"]??text}
  className={row=>cx("relative flex min-h-9 min-w-0 items-center gap-2 rounded-xl pe-2 text-body-regular outline-none transition-[background-color,color,box-shadow] duration-150 motion-reduce:transition-none group-data-[size=sm]/tree-view:min-h-8 group-data-[size=sm]/tree-view:text-body-2-regular",row.isDisabled?"cursor-default text-text-placeholder":"cursor-pointer text-text-primary",(row.isHovered||row.isSelected)&&!row.isDisabled&&"bg-dropdown-item-hover-background",row.isFocusVisible&&"ring-2 ring-inset ring-border-focus-ring",typeof className==="function"?className(row):className)}
  style={row=>({"--tree-item-level":row.level,paddingInlineStart:`calc(0.5rem + ${row.level-1} * 1.25rem)`,...(typeof style==="function"?style(row):style)} as CSSProperties)}>
  <TreeItemContent>{row=>{const Glyph=row.isExpanded?(expandedIcon??icon??(row.hasChildItems?RiFolderOpenLine:RiFileLine)):(icon??(row.hasChildItems?RiFolder3Line:RiFileLine));return <>
   <Guides row={row}/><span className="flex shrink-0 items-center gap-1">
    {row.hasChildItems?<AriaButton slot="chevron" aria-label={row.isExpanded?"Collapse":"Expand"} className={cx("flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground-icon-tertiary outline-none transition-colors hover:text-foreground-icon-primary data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring [&_svg]:opacity-50 [&_svg]:transition-transform [&_svg]:duration-150 motion-reduce:[&_svg]:transition-none",row.isExpanded?"[&_svg]:rotate-90":direction==="rtl"?"[&_svg]:rotate-180":undefined)} render={buttonProps=><IconButton {...buttonProps} unstyled size="small" icon={RiArrowRightSLine} aria-label={row.isExpanded?"Collapse":"Expand"}/>}/>:<span aria-hidden className={cx("h-5 shrink-0",row.level===1?"w-5":"w-2")}/>}
    <Glyph aria-hidden className={cx("size-4 shrink-0 opacity-50",row.isDisabled?"text-foreground-icon-disabled":row.hasChildItems?"text-foreground-icon-primary":fileTone(text),iconClassName)}/>
   </span><span className="min-w-0 flex-1 truncate text-start"><bdi>{label}</bdi></span>
   {trailingContent!=null&&<span className="shrink-0 text-caption-1-medium text-text-tertiary">{trailingContent}</span>}
  </>}}</TreeItemContent>{children}
 </AriaTreeItem>
}
export const TreeViewItem=forwardRef(TreeViewItemInner) as <T=object>(props:TreeViewItemProps<T>&RefAttributes<HTMLDivElement>)=>ReactElement;

